with kept_keys as (select id from suppliers except select id from suppliers where rating < 3.8), verified as (select s.* from suppliers s inner join kept_keys k on s.id = k.id) select case when rating >= 3.6 then 'LARGE' else 'SMALL' end as rating_tier, city, count_if(country = 'DE') as de_events, percentile_approx(rating, array(0.25, 0.5, 0.75)) as rating_quartiles from verified group by grouping sets ((case when rating >= 3.6 then 'LARGE' else 'SMALL' end, city), (case when rating >= 3.6 then 'LARGE' else 'SMALL' end));
